{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create Or Replace table zeproc_db.maplemonk.zeproc_catalog_porduct_master as select attribute_id, entity_id, value::string as Value from zeproc_db.maplemonk.zeproc_magento_catalog_product_entity_varchar qualify row_number() over(partition by entity_id,attribute_id order by case when store_id = 3 and value is not null then 2 when store_id = 0 and value is not null then 1 else 0 end desc ) = 1 UNION ALL select attribute_id, entity_id, value::string as Value from zeproc_db.maplemonk.zeproc_magento_catalog_product_entity_int qualify row_number() over(partition by entity_id,attribute_id order by case when store_id = 3 and value is not null then 2 when store_id = 0 and value is not null then 1 else 0 end desc ) = 1 UNION ALL select attribute_id, entity_id, value::string as Value from zeproc_db.maplemonk.zeproc_magento_catalog_product_entity_text qualify row_number() over(partition by entity_id,attribute_id order by case when store_id = 3 and value is not null then 2 when store_id = 0 and value is not null then 1 else 0 end desc ) = 1 UNION ALL select attribute_id, entity_id, value::string as Value from zeproc_db.maplemonk.zeproc_magento_catalog_product_entity_decimal qualify row_number() over(partition by entity_id,attribute_id order by case when store_id = 3 and value is not null then 2 when store_id = 0 and value is not null then 1 else 0 end desc ) = 1 UNION ALL select attribute_id, entity_id, value::string as Value from zeproc_db.maplemonk.zeproc_magento_catalog_product_entity_datetime qualify row_number() over(partition by entity_id,attribute_id order by case when store_id = 3 and value is not null then 2 when store_id = 0 and value is not null then 1 else 0 end desc ) = 1 ; Create Or REPLACE table zeproc_db.maplemonk.zeproc_catalog_leaf_Category as with cte as ( SELECT ccp.product_id as entity_id, cce.entity_id AS category_id FROM zeproc_db.maplemonk.zeproc_magento_catalog_category_product AS ccp INNER JOIN zeproc_db.maplemonk.zeproc_magento_catalog_category_entity AS cce ON cce.entity_id = ccp.category_id WHERE NOT EXISTS ( SELECT 1 FROM zeproc_db.maplemonk.zeproc_magento_catalog_category_entity AS child WHERE child.parent_id = cce.entity_id ) ) select c.* ,en.value as Category_Name_eng ,nr.value as Category_Name_local from cte c left join ( SELECT store_id,entity_id as category_id,value FROM zeproc_db.maplemonk.zeproc_magento_catalog_category_entity_varchar WHERE attribute_id = 45 and store_id = 0 qualify row_number() over(partition by category_id order by 1)= 1 )en on c.category_id = en.category_id left join ( SELECT store_id,entity_id as category_id,value FROM zeproc_db.maplemonk.zeproc_magento_catalog_category_entity_varchar WHERE attribute_id = 45 and store_id = 3 qualify row_number() over(partition by category_id order by 1)= 1 )nr on c.category_id = nr.category_id qualify row_number() over(partition by entity_id order by 1)= 1 ; CREATE OR REPLACE TABLE zeproc_db.maplemonk.zeproc_catalog_product_master_final AS With SP as ( SELECT entity_id, SKU, type_id, updated_at, ATTRIBUTE_SET_ID, REQUIRED_OPTIONS, PARENT_SKU as PARENT_SKU_ID, parent_id as parent_id, \"\'all_attributes_input\'\" AS all_attributes_input, \"\'aql\'\" AS aql, \"\'area_of_use\'\" AS area_of_use, \"\'article_no\'\" AS article_no, \"\'brand\'\" AS brand, \"\'certification_text\'\" AS certification_text, \"\'certifications\'\" AS certifications, \"\'color\'\" AS color, \"\'color_family\'\" AS color_family, \"\'country_of_manufacture\'\" AS country_of_manufacture, REGEXP_REPLACE(\"\'description\'\", \'<[^>]+>\', \'\') AS description, \"\'downloads\'\" AS downloads, \"\'ean\'\" AS ean, \"\'enable_product_matrix\'\" AS enable_product_matrix, \"\'feed_description_internal\'\" AS feed_description_internal, \"\'finger_thickness_mm\'\" AS finger_thickness_mm, \"\'gender\'\" AS gender, \"\'googleshopping_exclude\'\" AS googleshopping_exclude, \"\'gtin\'\" AS gtin, \"\'has_options\'\" AS has_options, \"\'image\'\" AS image, \"\'is_customizable\'\" AS is_customizable, \"\'lastname\'\" AS lastname, \"\'length_mm\'\" AS length_mm, \"\'material\'\" AS material, \"\'material_multiselect\'\" AS material_multiselect, \"\'material_thickness\'\" AS material_thickness, \"\'meta_description\'\" AS meta_description, \"\'meta_keyword\'\" AS meta_keyword, \"\'meta_title\'\" AS meta_title, \"\'model_number\'\" AS model_number, \"\'name\'\" AS name, \"\'name_2\'\" AS name_2, \"\'nobb_number\'\" AS nobb_number, \"\'package_quantity_pairs\'\" AS package_quantity_pairs, \"\'package_quantity_pieces\'\" AS package_quantity_pieces, \"\'palm_thickness_mm\'\" AS palm_thickness_mm, \"\'parent_sku\'\" AS parent_sku, \"\'parent_sku_old\'\" AS parent_sku_old, \"\'pdf_labels\'\" AS pdf_labels, \"\'pdf_links\'\" AS pdf_links, \"\'price\'\" AS price, \"\'quantity_and_stock_status\'\" AS quantity_and_stock_status, \"\'safety_class\'\" AS safety_class, \"\'shipping_from\'\" AS shipping_from, \"\'short_description\'\" AS short_description, \"\'size\'\" AS size, \"\'size_family\'\" AS size_family, \"\'sku\'\" AS attr_sku, \"\'small_image\'\" AS small_image, \"\'special_from_date\'\" AS special_from_date, \"\'special_price\'\" AS special_price, \"\'special_to_date\'\" AS special_to_date, \"\'status\'\" AS status, \"\'store_id\'\" AS store_id, \"\'sup_price_ref_key\'\" AS sup_price_ref_key, \"\'supplier_id\'\" AS supplier_id, \"\'supplier_name\'\" AS supplier_name, \"\'supplier_product_url\'\" AS supplier_product_url, \"\'supplier_type\'\" AS supplier_type, \"\'table_content\'\" AS table_content, \"\'tax_class_id\'\" AS tax_class_id, \"\'thumbnail\'\" AS thumbnail, \"\'type\'\" AS type, \"\'unspsc\'\" AS unspsc, \"\'uom\'\" AS uom, \"\'url_key\'\" AS url_key, \"\'url_path\'\" AS url_path, \"\'visibility\'\" AS visibility, \"\'voltage\'\" AS voltage, \"\'washing_instructions_final\'\" AS washing_instructions_final, \"\'whats_in_the_package\'\" AS whats_in_the_package, \"\'zeproc_uom\'\" AS zeproc_uom, \"\'category_ids\'\" as category_ids, \"\'auto_pricing_min_price\'\" AS auto_min_price, \"\'model_name\'\" AS model_name, \"\'company_id\'\" AS company_id, \"\'company_name\'\" AS company_name, \"\'model_name\'\" AS model_name, \"\'cost_of_goods_sold\'\" as cogs FROM ( SELECT pm.entity_id, case when FRONTEND_INPUT = \'select\' AND SOURCE_MODEL like \'Magento_Eav_Model_Entity_Attribute_Source_Table\' then other_Value else pm.value end value, ea.attribute_code ,SKU ,ATTRIBUTE_SET_ID ,type_id ,updated_at ,HAS_OPTIONS ,REQUIRED_OPTIONS ,PARENT_SKU ,parent_id FROM ( SELECT n.entity_id ,n.sku ,attribute_id ,value ,n.type_id ,n.updated_at ,n.HAS_OPTIONS ,n.ATTRIBUTE_SET_ID ,n.REQUIRED_OPTIONS from( select * FROM zeproc_db.maplemonk.zeproc_magento_catalog_product_entity QUALIFY ROW_NUMBER() OVER (PARTITION BY entity_id ORDER BY entity_id) = 1 )n left join zeproc_db.maplemonk.zeproc_catalog_porduct_master pm on n.entity_id = pm.entity_id ) pm LEFT JOIN ( SELECT * FROM zeproc_db.maplemonk.zeproc_magento_eav_attribute QUALIFY ROW_NUMBER() OVER (PARTITION BY attribute_id ORDER BY attribute_id) = 1 ) ea ON pm.attribute_id = ea.attribute_id left join ( SELECT option_id,value as other_Value FROM zeproc_db.maplemonk.zeproc_magento_eav_attribute_option_value qualify row_number() over(partition by option_id order by length(ifnull(value,\'\')) asc) = 1 )val on trim(value::string) = trim(option_id::string) left join ( select product_id, parent_id,sku as PARENT_SKU from zeproc_db.maplemonk.zeproc_magento_catalog_product_super_link dv left join ( select * from zeproc_db.maplemonk.zeproc_magento_catalog_product_entity qualify row_number() over(partition by entity_id order by 1) = 1 )pm on dv.parent_id = pm.entity_id qualify row_number() over(partition by product_id order by 1) =1 )dbl on dbl.product_id = pm.entity_id ) PIVOT ( MAX(value) FOR attribute_code IN ( \'all_attributes_input\', \'aql\', \'area_of_use\', \'article_no\', \'brand\', \'certification_text\', \'certifications\', \'color\', \'color_family\', \'country_of_manufacture\', \'description\', \'downloads\', \'ean\', \'enable_product_matrix\', \'feed_description_internal\', \'finger_thickness_mm\', \'gender\', \'googleshopping_exclude\', \'gtin\', \'has_options\', \'image\', \'is_customizable\', \'lastname\', \'length_mm\', \'material\', \'material_multiselect\', \'material_thickness\', \'meta_description\', \'meta_keyword\', \'meta_title\', \'model_number\', \'name\', \'name_2\', \'nobb_number\', \'package_quantity_pairs\', \'package_quantity_pieces\', \'palm_thickness_mm\', \'parent_sku\', \'parent_sku_old\', \'pdf_labels\', \'pdf_links\', \'price\', \'quantity_and_stock_status\', \'safety_class\', \'shipping_from\', \'short_description\', \'size\', \'size_family\', \'sku\', \'small_image\', \'special_from_date\', \'special_price\', \'special_to_date\', \'status\', \'store_id\', \'sup_price_ref_key\', \'supplier_id\', \'supplier_name\', \'supplier_product_url\', \'supplier_type\', \'table_content\', \'tax_class_id\', \'thumbnail\', \'type\', \'unspsc\', \'uom\', \'url_key\', \'url_path\', \'visibility\', \'voltage\', \'washing_instructions_final\', \'whats_in_the_package\', \'zeproc_uom\', \'category_ids\', \'auto_pricing_min_price\', \'model_name\', \'company_id\', \'company_name\', \'model_name\', \'cost_of_goods_sold\' ) ) AS p ) select sp.*, ps.visibility as Parent_SKU_visibility, ps.status as Parent_SKU_Status, pid.category_id as category_id_New, pid.category_name, ps1.visibility as Parent_SKU_ID_visibility, ps1.status as Parent_SKU_ID_Status, cl.CATEGORY_ID as leaf_CATEGORY_ID, cl.CATEGORY_NAME_ENG as Leaf_CATEGORY_NAME_ENG, cl.CATEGORY_NAME_LOCAL as Leaf_CATEGORY_NAME_LOCAL from sp left join ( select parent_sku,visibility , status from sp where sku = parent_sku )ps on sp.parent_sku = ps.parent_sku left join ( select * from ( select SKU parent_sku_id,visibility , status from sp ) qualify row_number() over(partition by parent_sku_id order by 1) = 1 )ps1 on sp.parent_sku_id = ps1.parent_sku_id left join ( SELECT product_id, listagg(ccp.category_id,\'|\') AS category_id, listagg( ccev.value,\'|\') AS category_name FROM zeproc_db.maplemonk.zeproc_magento_catalog_category_product ccp JOIN zeproc_db.maplemonk.zeproc_magento_catalog_category_entity cce ON cce.entity_id = ccp.category_id LEFT JOIN zeproc_db.maplemonk.zeproc_magento_catalog_category_entity_varchar ccev ON ccev.entity_id = cce.entity_id AND ccev.attribute_id = ( SELECT attribute_id FROM zeproc_db.maplemonk.zeproc_magento_eav_attribute WHERE attribute_code = \'name\' AND entity_type_id = ( SELECT entity_type_id FROM zeproc_db.maplemonk.zeproc_magento_eav_entity_type WHERE entity_type_code = \'catalog_category\' ) ) AND ccev.store_id = 0 group by 1 )pid on sp.entity_id = pid.product_id left join zeproc_db.maplemonk.zeproc_catalog_leaf_Category cl on sp.entity_id = cl.entity_id ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from ZEPROC_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            